let out = $input.item.json;
let raw = "";
if (Array.isArray(out)) {
  const msg = out.find(o => o.type === 'message') || out[0];
  const contentItem = msg?.content?.find(c => c.type === 'output_text') || msg?.content?.[0];
  raw = contentItem?.text ?? '';
} else {
  raw = out.content ?? out.text ?? '';
}
raw = String(raw).trim().replace(/^```json/i, "").replace(/^```/, "").replace(/```$/, "").trim();
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { error: "Could not parse AI response as JSON", raw };
}
return { json: parsed };
